SELECT s1."c0" AS "a", s1."c1" AS "b", s1."c2" AS "g", s1."c3" AS "l" FROM (SELECT s2."c0" AS "c0", s2."c1" AS "c1", (CASE WHEN (s2."c0" IS NULL) THEN CAST(NULL AS NUMBER(38,0)) ELSE (CASE WHEN (s2."c1" IS NULL) THEN CAST(NULL AS NUMBER(38,0)) ELSE GREATEST_IGNORE_NULLS(s2."c0", s2."c1") END) END) AS "c2", LEAST_IGNORE_NULLS(s2."c0", s2."c1") AS "c3" FROM (SELECT v."c0" AS "c0", v."c1" AS "c1" FROM (VALUES (1, CAST(NULL AS NUMBER(38,0))), (1, 5)) AS v("c0", "c1")) AS s2) AS s1
